"""Bike-share docking: finalize a bike return, update the station's
inventory, and settle the rider's bill for the completed trip."""

from dataclasses import dataclass, field
from typing import List

GEOFENCE_RADIUS_M = 15
LOW_BATTERY_PCT = 20


class DockingError(Exception):
    pass


@dataclass
class Bike:
    bike_id: str
    is_electric: bool
    battery_level: int
    needs_maintenance: bool = False


@dataclass
class Ride:
    bike_id: str
    duration_minutes: int
    distance_from_station_m: float
    flagged_lost: bool = False
    fee_cents: int = 0


@dataclass
class Plan:
    free_minutes: int
    max_ride_minutes: int
    overage_rate_cents: int


@dataclass
class Dock:
    dock_id: str
    lock_engaged: bool
    supports_charging: bool


@dataclass
class Station:
    station_id: str
    capacity: int
    bikes_present: int
    available_charging_docks: int
    docked_bikes: List[str] = field(default_factory=list)


def complete_dock_event(bike, station, dock, ride, plan):
    """Register a returned bike at its station and close out the ride,
    including any fee owed for time beyond the plan's covered minutes."""

    if ride.distance_from_station_m > GEOFENCE_RADIUS_M:
        raise DockingError("bike is too far from the station to dock")

    if station.bikes_present >= station.capacity:
        raise DockingError("station has no open docks")

    needs_charging_dock = bike.is_electric and bike.battery_level < LOW_BATTERY_PCT
    if needs_charging_dock and station.available_charging_docks <= 0:
        raise DockingError("no charging dock free for a low battery bike")

    if needs_charging_dock and not dock.supports_charging:
        raise DockingError("assigned dock cannot charge this bike")

    if not dock.lock_engaged:
        raise DockingError("dock lock did not engage")

    station.bikes_present += 1
    station.docked_bikes.append(bike.bike_id)
    if needs_charging_dock:
        station.available_charging_docks -= 1

    if ride.duration_minutes > plan.max_ride_minutes:
        ride.flagged_lost = True

    if bike.battery_level < LOW_BATTERY_PCT:
        bike.needs_maintenance = True

    if ride.duration_minutes > plan.max_ride_minutes:
        overage_minutes = ride.duration_minutes - plan.max_ride_minutes
        ride.fee_cents = overage_minutes * plan.overage_rate_cents

    return ride
